"""Guard consultation: document bindings only; no event evaluator or product tests."""
from pathlib import Path
from collections import Counter
import datetime
import difflib
import hashlib
import json
import re
import subprocess

ROOT = Path('F:/ChnobelRuntime/reviews/v2-manifest-questions-04/guard')
OUT = Path('F:/ChnobelRuntime/verification/guard-question-04-returns-parent')
REPO = Path('F:/Projects/Chnobel')
BASE = 'bb4decf6c3b9d3bb945e1e3bb33dd0ea969bd29b'
DISPATCH_BASE = 'f6e73092dd1d5940506c145d645917abc601f1a6'
PINS = {'brief.md': 'e1b01395412a5a5c9612f2a1698d8db6d994b8d785b79487b321260a137e90ee',
        'input-bindings.json': '4fc3d507be0f40485a1b73f5788ab8cb546f98d275638940635f402505508bf3',
        'procedural-bindings.json': 'c3c116f891e975ed2e8959fe1fc7398cd411d2151c5bb2937a36d4031e64ebc7'}

def rawmeta(raw):
    return {'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw)}

def norm(path):
    return Path(path).as_posix()

def bind(path):
    return {'path': norm(path), **rawmeta(Path(path).read_bytes())}

def load(path):
    return json.loads(Path(path).read_bytes())

def same(a, b):
    assert a['sha256'] == b['sha256'] and a['bytes'] == b['bytes'], (a, b)

def check(b):
    assert re.fullmatch('[0-9a-f]{64}', b['sha256'])
    same(b, bind(b['path']))

def ptr(obj, pointer):
    assert pointer == '' or pointer.startswith('/')
    for part in pointer.split('/')[1:]:
        key = part.replace('~1', '/').replace('~0', '~')
        obj = obj[int(key)] if isinstance(obj, list) else obj[key]
    return obj

def walk(obj):
    if isinstance(obj, dict):
        yield obj
        for value in obj.values():
            yield from walk(value)
    elif isinstance(obj, list):
        for value in obj:
            yield from walk(value)

def unique(rows, key):
    result = {row[key]: row for row in rows}
    assert len(result) == len(rows)
    return result

def gitraw(commit, rel):
    return subprocess.check_output(['git', '-C', str(REPO), 'show', commit + ':' + rel])

def snapshot(rec):
    raw = rec['utf8Raw'].encode('utf-8')
    same(rec, rawmeta(raw))
    return raw

def ndelta(rec, before, after):
    assert rec['identical'] == (before == after)
    if rec['identical']:
        assert rec['lines'] == []
    else:
        assert ''.join(difflib.restore(rec['lines'], 1)).encode('utf-8') == before
        assert ''.join(difflib.restore(rec['lines'], 2)).encode('utf-8') == after

def replacement(rec, before, after):
    assert rec['encoding'] == 'full-replacement-utf8Raw'
    assert rec['changed'] == (before != after)
    assert (rec['replacementUtf8Raw'].encode('utf-8') if rec['changed'] else before) == after

assert subprocess.check_output(['git', '-C', str(REPO), 'rev-parse', 'HEAD']).decode().strip() == BASE
for name, sha in PINS.items():
    assert bind(ROOT / name)['sha256'] == sha
inp = load(ROOT / 'input-bindings.json')
proc = load(ROOT / 'procedural-bindings.json')
manifest_root = Path(inp['manifest']['path']).parent
frozen = inp['mandatoryFiles'] + proc['additionalProceduralSources'] + [bind(ROOT / n) for n in PINS]
by_path = unique([{'key': norm(x['path']), **x} for x in frozen], 'key')
assert len(inp['mandatoryFiles']) == inp['mandatoryFileCount'] == 36
assert len(by_path) == 42
for rec in frozen:
    check(rec)
for rec in proc['additionalProceduralSources']:
    assert snapshot(rec) == Path(rec['path']).read_bytes()
parent_bases = unique(proc['mutableParentContextsAtDispatch'], 'path')
assert len(parent_bases) == 3
selected = unique(inp['selectedCases'], 'caseId')
assert len(selected) == inp['selectedCaseCount'] == 6
assert Counter(c['scope'] for c in selected.values()) == {'PRIMARY_GUARD_CASE': 4, 'TEXTUAL_BOUNDARY_CONTROL': 2}
index = load(manifest_root / 'case-index-base.json')
handoff = load(manifest_root / 'handoff.json')
question = inp['originalQuestionProjection']
assert ptr(load(question['source']['path']), question['pointer']) == question['originalRecord']
assert set(question['originalRecord']['cases']) == {c['caseId'] for c in selected.values() if c['scope'] == 'PRIMARY_GUARD_CASE'}
for rec in selected.values():
    assert ptr(index, rec['pointer']) == rec['originalRecord']
    for field in ['input', 'oracle', 'scene']:
        check(rec[field])
        if field != 'scene':
            original = rec['originalRecord'][field]
            assert norm(manifest_root / original['path']) == norm(rec[field]['path'])
            same(original, rec[field])
assert len(inp['handoffSelectedProjections']) == 28
for rec in inp['handoffSelectedProjections']:
    assert ptr(handoff, rec['pointer']) == rec['originalRecord']
    assert norm(manifest_root / rec['originalRecord']['path']) == norm(rec['target']['path'])
    same(rec['originalRecord'], rec['target'])
    check(rec['target'])
cat = load(manifest_root / 'catalogue.json')
rules = load(manifest_root / 'rule-records.json')
claim_rules = unique(rules, 'claimId')
guard_ids = {r['id'] for r in cat['facts'] if r['id'].startswith('proof.')}
context_ids = {'observation.valid', 'attempt.submitted', 'observation.complete'}
assert len(guard_ids) == 5 and len(claim_rules) == 8
source_json = {norm(r['path']): load(r['path']) for r in frozen if Path(r['path']).suffix == '.json'}
results = []
matrices = {}
for role in ['didaktik', 'architekt']:
    directory = ROOT / role
    assert {x.name for x in directory.iterdir()} == {'report.md', 'sources.json', 'decision.json'}
    source, decision = load(directory / 'sources.json'), load(directory / 'decision.json')
    assert source['role'] == decision['role'] == role
    assert source['questionId'] == decision['questionId'] == 'Q-GUARD-TOTALISATION'
    assert decision['scopeStatus'] == 'COMPLETE' and decision['recommendation'] == 'PROPOSED_NOT_ACCEPTED'
    assert decision['wholeRoleStatus'] == 'INCOMPLETE_OTHER_QUESTIONS_PENDING'
    assert decision['wholeManifestVerdict'] == 'NOT_ISSUED'
    for key in ['recommendationsAccepted', 'implementationAuthorized', 'blockerClosed', 'ratificationIssued']:
        assert decision[key] is False
    assert set(decision['execution'].values()) == {'NOT_RUN'}
    for key, target in [('brief', ROOT/'brief.md'), ('input', ROOT/'input-bindings.json'), ('proceduralFreeze', ROOT/'procedural-bindings.json'), ('manifest', Path(inp['manifest']['path'])), ('report', directory/'report.md'), ('sources', directory/'sources.json')]:
        assert norm(decision[key]['path']) == norm(target)
        check(decision[key])
    sections = unique(decision['sectionAssessments'], 'sectionId')
    assert set(sections) == {'G1', 'G2', 'G3', 'G4', 'G5', 'G6'}
    expected_section_status = 'ANSWERED_BOUNDED' if role == 'didaktik' else 'COMPLETE'
    assert all(s['status'] == expected_section_status and s['assessment'] for s in sections.values())
    assert set(unique(decision['guardDefinitions'], 'factId')) == guard_ids
    assert set(unique(decision['contextDefinitions'], 'factId')) == context_ids
    word_count = len((directory/'report.md').read_text(encoding='utf-8').split())
    assert word_count <= 1500
    if role == 'didaktik':
        records = unique([{'key': norm(r['frozen']['path']), **r} for r in source['files']], 'key')
        assert set(records) == set(by_path)
        for path, r in records.items():
            for phase in ['frozen', 'before', 'after']:
                assert norm(r[phase]['path']) == path
                same(r[phase], by_path[path])
            assert r['semanticReadRanges'] and r['beforeMatchesFrozen'] and r['afterMatchesFrozen'] and r['rawBeforeAfterEqual']
        assert source['noPeerReportsRead'] and source['noParentEvaluationFilesRead'] and source['noTranscriptsRead']
        assert source['wholeReadSetUnchanged'] is False and source['atomicWholeReadSetClaimed'] is False
    else:
        records = unique([{'key': norm(r['path']), **r} for group in ['mandatorySources', 'proceduralSources', 'dispatchSources'] for r in source[group]], 'key')
        afters = unique(source['finalBindingCapture']['afterSources'], 'path')
        assert set(records) == set(by_path) == set(afters)
        for path, r in records.items():
            same(r['before'], by_path[path]); same(afters[path]['after'], by_path[path])
            if 'frozen' in r:
                same(r['frozen'], by_path[path])
            assert r['semanticReadRanges'] and afters[path]['rawUnchanged']
        assert source['peerReportsRead'] is False and source['parentEvaluationReportsRead'] is False and source['transcriptsRead'] is False
        assert source['atomicReadSetClaimed'] is False and source['finalBindingCapture']['wholeReadSetUnchanged'] is False
    contexts = unique(source['mutableParentContexts'], 'path')
    assert set(contexts) == set(parent_bases)
    context_results = []
    for path, r in contexts.items():
        frozen_raw = snapshot(parent_bases[path]); before = snapshot(r['before'])
        rel = Path(path).relative_to(REPO).as_posix()
        old_git, new_git = gitraw(DISPATCH_BASE, rel), gitraw(BASE, rel)
        assert old_git == frozen_raw.replace(b'\r\n', b'\n')
        if role == 'didaktik':
            assert snapshot(r['frozenBase']) == frozen_raw
            after = snapshot(r['after'])
            for field, a, b in [('baselineToBeforeRawDelta', frozen_raw, before), ('beforeToAfterRawDelta', before, after), ('baselineToAfterRawDelta', frozen_raw, after)]:
                ndelta(r[field], a, b)
            gitrec = r['gitBaselineSeparateFromWorktree']
            assert snapshot(gitrec) == old_git and gitrec['commit'] == DISPATCH_BASE
            ndelta(gitrec['gitToFrozenWorktreeRawDelta'], old_git, frozen_raw)
            same(gitrec['afterBinding'], rawmeta(old_git))
        else:
            assert snapshot(r['frozenBasis']) == frozen_raw
            final = next(x for x in source['finalBindingCapture']['mutableParentContexts'] if x['path'] == path)
            after = snapshot(final['after'])
            replacement(r['beforeDeltaFromFrozen'], frozen_raw, before)
            replacement(final['afterDeltaFromBefore'], before, after)
            replacement(final['afterDeltaFromFrozen'], frozen_raw, after)
            gitrec = final['gitLFComparison']; same(gitrec['gitLF'], rawmeta(old_git))
            assert gitrec['gitCheckpoint'] == DISPATCH_BASE
            for key, expected in [('gitEqualsFrozenRaw', old_git == frozen_raw), ('gitEqualsFrozenCRLFtoLF', old_git == frozen_raw.replace(b'\r\n', b'\n')), ('gitEqualsCurrentRaw', old_git == after), ('gitEqualsCurrentCRLFtoLF', old_git == after.replace(b'\r\n', b'\n'))]:
                assert gitrec[key] == expected
        assert before == frozen_raw and after == Path(path).read_bytes()
        assert new_git == after.replace(b'\r\n', b'\n')
        context_results.append({'path': path, 'frozen': rawmeta(frozen_raw), 'before': rawmeta(before), 'after': rawmeta(after), 'threeTransitionsReconstructed': True, 'changedTransitions': sum(a != b for a, b in [(frozen_raw, before), (before, after), (frozen_raw, after)]), 'gitLFComparedSeparately': True})
    cases = unique(decision['cases'], 'caseId'); assert set(cases) == set(selected)
    counts = Counter(); seen_events = set(); seen_help = set()
    for cid, case in cases.items():
        selected_case = selected[cid]
        assert case['scope'] == selected_case['scope'] and case['indexPointer'] == selected_case['pointer']
        assert case['originalIndexRecord'] == selected_case['originalRecord']
        for field in ['input', 'oracle', 'scene']:
            rec = case[field + 'Binding'] if role == 'didaktik' else case[field]
            assert norm(rec['path']) == norm(selected_case[field]['path']); check(rec)
        actual_input = load(selected_case['input']['path']); actual_oracle = load(selected_case['oracle']['path'])
        assert case['originalOracleSnapshot' if role == 'didaktik' else 'existingOracle'] == actual_oracle
        assert case['sceneSnapshot' if role == 'didaktik' else 'sceneDeclaration'] == load(selected_case['scene']['path'])
        fact_rows = {}
        for field, required in [('guardRecommendations', guard_ids), ('contextFacts', context_ids), ('otherRequiredFacts', None)]:
            rows = unique(case[field], 'factId')
            if required is not None:
                assert set(rows) == required
            assert not set(rows) & set(fact_rows); fact_rows.update(rows); counts[field] += len(rows)
            for fid, row in rows.items():
                reference = row['catalogueReference' if role == 'didaktik' else 'catalogueSource']
                assert ptr(cat, reference['pointer'])['id'] == fid
                assert row['originalOracleValue' if role == 'didaktik' else 'existingOracleValue'] == actual_oracle['facts'][fid]
                assert row['reason'] and row['proposedValue'] in ('wahr', 'falsch', 'unbekannt', None)
                if row['proposedValue'] is None:
                    assert row['status'] == 'SPECIFICATION_PENDING' and row['conditionalAssignments']
        claims = unique(case['claimDecisionRecommendations'], 'claimId'); assert set(claims) == set(claim_rules)
        counts['claimRows'] += len(claims)
        for claim_id, row in claims.items():
            rule = claim_rules[claim_id]; requires = rule['logic']['requires']
            assert row['requiresSnapshot' if role == 'didaktik' else 'logicRequires'] == requires
            assert row['originalOracleDecision' if role == 'didaktik' else 'existingOracleDecision'] == actual_oracle['decisions'][claim_id]
            if role == 'didaktik':
                assert ptr(rules, row['ruleReference']['pointer']) == rule
                assert row['wordingSnapshot'] == rule['boundary']['wording']
                bindings = row['allRequirementBindings'] + row['noneRequirementBindings']
                for side in ['all', 'none']:
                    assert [x['factId'] for x in row[side+'RequirementBindings']] == requires[side]
                for x in bindings:
                    assert ptr(decision, x['decisionDocumentPointer']) == fact_rows[x['factId']]
            else:
                assert ptr(rules, row['ruleSource']['pointer']) == requires
                assert row['ruleId'] == rule['id'] and row['ruleVersion'] == rule['version']
                bindings = row['requiredFacts']
                assert [x['factId'] for x in bindings] == requires['all'] + requires['none']
            for x in bindings:
                assert x['proposedValue'] == fact_rows[x['factId']]['proposedValue']
                assert x['requiredValue'] == ('wahr' if x['factId'] in requires['all'] else 'falsch')
            if row.get('status', row.get('decisionStatus')) == 'SPECIFICATION_PENDING':
                assert row.get('conditionalAssignments') or row.get('conditionalDecision')
                counts['conditionalClaimRows'] += 1
        event_inventory = case['sourceEventInventory' if role == 'didaktik' else 'eventReferenceCatalogue']
        help_inventory = case['sourceSupportInventory' if role == 'didaktik' else 'helpReferenceCatalogue']
        assert {x['pointer'] for x in event_inventory} == {f'/events/{i}' for i in range(len(actual_input['events']))}
        assert {x['pointer'] for x in help_inventory} == {f'/supportEvidence/{i}' for i in range(len(actual_input['supportEvidence']))}
    for rec in walk(decision):
        if 'path' not in rec or 'pointer' not in rec:
            continue
        path = norm(rec['path']); pointer = rec['pointer']
        if path not in source_json:
            continue
        target = ptr(source_json[path], pointer)
        if 'eventId' in rec and pointer.startswith('/events/'):
            for key, value in rec.items():
                if key not in ['path', 'pointer']:
                    assert value == (target['eventId'] if key == 'eventId' else target[key]), (path, pointer, key)
            seen_events.add((path, pointer)); counts['eventReferenceComparisons'] += 1
        if 'evidenceId' in rec and pointer.startswith('/supportEvidence/'):
            for key, value in rec.items():
                if key not in ['path', 'pointer']:
                    assert value == target[key], (path, pointer, key)
            seen_help.add((path, pointer)); counts['supportReferenceComparisons'] += 1
    assert counts['guardRecommendations'] == 30 and counts['contextFacts'] == 18 and counts['claimRows'] == 48
    if role == 'didaktik':
        index_records = source['indexChecks']; assert len(index_records) == 35
        for r in index_records:
            assert ptr(load(r['source']['path']), r['pointer']) == r['actualOriginalRecord'] and r['recordEqual']
    else:
        capture = source['finalBindingCapture']['indexAndTargetComparisons']
        assert len(capture['selectedRecords']) == 6 and len(capture['handoffRecords']) == 28
        for r in capture['selectedRecords']:
            assert ptr(index, r['pointer']) == r['actualOriginalRecord'] and r['equalsFrozenProjection']
        for r in capture['handoffRecords']:
            assert ptr(handoff, r['pointer']) == r['actualOriginalRecord'] and r['equalsFrozenProjection']
        assert capture['question']['actualOriginalRecord'] == question['originalRecord']
    matrices[role] = {cid: {group: {r['factId'] if group != 'claimDecisionRecommendations' else r['claimId']: {k: r[k] for k in ['proposedValue', 'proposedDecision', 'conditions', 'conditionalOn', 'conditionalAssignments', 'conditionalDecision', 'status', 'decisionStatus'] if k in r} for r in c[group]} for group in ['guardRecommendations', 'contextFacts', 'otherRequiredFacts', 'claimDecisionRecommendations']} for cid, c in cases.items()}
    results.append({'role': role, 'status': 'PASS_DOCUMENT_BINDINGS_WITH_RETAINED_PROCEDURAL_EXCEPTIONS', 'files': [bind(directory/f) for f in ['report.md', 'sources.json', 'decision.json']], 'mandatoryFiles': 36, 'immutableSourceBindings': 42, 'proceduralSources': 3, 'contexts': context_results, 'indexProjections': 35, 'caseCount': len(cases), 'counts': dict(counts), 'uniqueEventReferences': len(seen_events), 'uniqueSupportReferences': len(seen_help), 'reportWhitespaceWords': word_count, 'wholeReadSetUnchanged': False, 'recommendationsAccepted': False})
for rec in frozen:
    check(rec)
result = {'kind': 'guard-question-parent-document-binding-verification/1', 'at': datetime.datetime.now().astimezone().isoformat(), 'status': 'PASS_DOCUMENT_BINDINGS_WITH_RETAINED_PROCEDURAL_EXCEPTIONS', 'scope': 'DOCUMENT_COUNTS_BINDINGS_POINTERS_AND_RAW_CONTEXT_RECONSTRUCTION_ONLY', 'parentBase': BASE, 'dispatchBase': DISPATCH_BASE, 'helper': bind(__file__), 'brief': bind(ROOT/'brief.md'), 'input': bind(ROOT/'input-bindings.json'), 'proceduralFreeze': bind(ROOT/'procedural-bindings.json'), 'roles': results, 'matrixProjections': matrices, 'parentInspectionIncidents': bind(OUT/'inspection-incidents.json'), 'wholeManifestVerdict': 'NOT_ISSUED', 'implementationAuthorized': False, 'recommendationsAccepted': False, 'ratificationIssued': False, 'blockerClosed': False, 'productSchemaEvaluatorTestsNative': 'NOT_RUN', 'semanticEvaluationPerformed': False, 'historicalShellReadbackHashesReexecuted': False, 'qualifications': ['Authorisations and normative recommendations are not decided by this helper.', 'Whole-readset atomicity and whole-procedure PASS are not claimed.', 'Didaktik startup measurement order, captured shell failure and historical intermediate output hashes remain attributed to its source protocol; final files independently checked.', 'Architecture capturecache outside F: and refused whole-file write retained; no retroactive permission.', 'Parent capture exceptions retained separately.']}
target = OUT/'verification.json'
assert not target.exists(), 'Preserve prior verification; choose a separate attempt path.'
with target.open('x', encoding='utf-8', newline='\n') as output:
    json.dump(result, output, ensure_ascii=False, indent=2); output.write('\n')
print(json.dumps({'status': result['status'], 'evidence': bind(target), 'roles': [{k: r[k] for k in ['role', 'caseCount', 'counts', 'uniqueEventReferences', 'uniqueSupportReferences', 'reportWhitespaceWords']} for r in results]}, ensure_ascii=False))
